# Step 5: Create an online table for low-latency lookup
print("Creating online table...")

source_table_full_name = f"{CATALOG}.{SCHEMA}.{FEATURE_TABLE_NAME}"

try:
    online_table = wc.online_tables.create_and_wait(
        table={
            "name": ONLINE_TABLE_NAME,
            "catalog_name": CATALOG,
            "schema_name": SCHEMA,
            "source_table_full_name": source_table_full_name,
            "primary_key_columns": ["account_id"],
            "num_shards": 1
        }
    )
    print(f"Created online table: {online_table.name}")
except Exception as e:
    print(f"Error creating online table: {e}")
    # Try alternative approach using feature store
    print("Trying feature store publish approach...")
    try:
        publish_response = wc.feature_store.publish_table(
            source_table_name=source_table_full_name,
            publish_spec={
                "name": ONLINE_TABLE_NAME,
                "primary_key_columns": ["account_id"]
            }
        )
        print(f"Published online table via feature store: {publish_response}")
    except Exception as e2:
        print(f"Error with feature store publish: {e2}")
